def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and not seen[r][c]:
                comp=[]; q=deque([(r,c)]); seen[r][c]=True; touch=False
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    if a in (0,h-1) or b in (0,w-1): touch=True
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]==bg and not seen[na][nb]:
                            seen[na][nb]=True;q.append((na,nb))
                if touch: continue
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if len(comp)!=(r1-r0+1)*(c1-c0+1): continue
                for a,b in comp: out[a][b]=4
                if r1-r0+1==2 and r1+2<h and all(g[r1+2][cc]==bg for cc in range(c0,c1+1)):
                    for cc in range(c0,c1+1): out[r1+1][cc]=4
    return out

import collections

def transform(grid):
    h, w = len(grid), len(grid[0])
    A = B = None; orient = None
    for i in range(h):
        if len(set(grid[i])) == 1:
            a = [r[:w] for r in grid[:i]]; b = [r[:w] for r in grid[i+1:]]
            if a and b and len(a) == len(b):
                A, B, orient = a, b, 'row'; break
    if A is None:
        for j in range(w):
            if len(set(grid[i][j] for i in range(h))) == 1:
                a = [r[:j] for r in grid]; b = [r[j+1:] for r in grid]
                if a and b and len(a[0]) == len(b[0]):
                    A, B, orient = a, b, 'col'; break
    cnt = collections.Counter()
    for r in range(len(A)):
        for c in range(len(A[0])):
            if A[r][c] == B[r][c]:
                cnt[A[r][c]] += 1
    bg = cnt.most_common(1)[0][0]
    return [[3 if A[r][c] == B[r][c] else bg for c in range(len(A[0]))] for r in range(len(A))]

